/* @lc app=leetcode id=2398 lang=kotlin */
class Solution { fun maximumRobots(chargeTimes: IntArray, runningCosts: IntArray, budget: Long): Int = java.util.ArrayDeque<Int>().let { dq -> runningCosts.indices.fold(Triple(0, 0L, 0)) { (i, sum, maxLen), j -> (sum + runningCosts[j]).let { s -> generateSequence { dq.peekLast()?.takeIf { chargeTimes[it] <= chargeTimes[j] }?.also { dq.pollLast() } }.count().run { dq.addLast(j) }.run { generateSequence(Triple(i, s, dq)) { (cI, cS, cD) -> if (cD.isNotEmpty() && (chargeTimes[cD.peekFirst()] + (j - cI + 1).toLong() * cS > budget)) (if (cD.peekFirst() == cI) cD.pollFirst() else 0).run { Triple(cI + 1, cS - runningCosts[cI], cD) } else null }.last().let { (fI, fS, _) -> Triple(fI, fS, maxOf(maxLen, j - fI + 1)) } } } }.third } }